-- Structure only: no backfill, no change to legacy invoice/payment facts.
-- Service stage 2 must enforce active membership, atomic residual settlement,
-- receipt completion, append-only history, replay/fingerprint checks and audit.
ALTER TABLE `card_invoices` ADD COLUMN `closes_on` text CONSTRAINT `card_invoices_closes_on_check` CHECK (
  `closes_on` IS NULL OR (
    length(`closes_on`) = 10
    AND `closes_on` GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'
    AND `closes_on` >= '0001-01-01'
    AND date(`closes_on`, '+0 days') IS NOT NULL
    AND date(`closes_on`, '+0 days') = `closes_on`
  )
);
