-- Transitional guard: the old API still cannot insert a second unlinked payment.
-- Multiple payments of one invoice are possible with distinct validated operations.
CREATE UNIQUE INDEX `invoice_payments_legacy_invoice_unique` ON `invoice_payments` (`invoice_id`) WHERE `operation_id` IS NULL;
