CREATE TRIGGER `invoice_payments_operation_update` BEFORE UPDATE ON `invoice_payments`
FOR EACH ROW WHEN
  (OLD.`operation_id` IS NOT NULL AND NEW.`operation_id` IS NOT OLD.`operation_id`)
  OR EXISTS (
    SELECT 1 FROM `invoice_payments` p WHERE p.`id` = NEW.`id` AND p.`id` IS NOT OLD.`id`
      AND p.`operation_id` IS NOT NULL AND p.`operation_id` IS NOT NEW.`operation_id`
  )
  OR (NEW.`operation_id` IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM `invoice_payment_operations` o
    WHERE o.`id` = NEW.`operation_id` AND o.`kind` = 'payment'
      AND o.`household_id` = NEW.`household_id` AND o.`invoice_id` = NEW.`invoice_id`
      AND o.`account_id` = NEW.`account_id` AND o.`created_by_user_id` = NEW.`created_by_user_id`
      AND o.`amount_cents` = NEW.`amount_cents` AND o.`occurred_on` = NEW.`paid_at`
  ))
  OR EXISTS (
    SELECT 1 FROM `invoice_payment_operations` r WHERE r.`reversed_payment_id` IN (OLD.`id`, NEW.`id`)
      AND (r.`household_id` IS NOT NEW.`household_id` OR r.`invoice_id` IS NOT NEW.`invoice_id`
        OR r.`account_id` IS NOT NEW.`account_id` OR r.`amount_cents` IS NOT NEW.`amount_cents`)
  )
BEGIN SELECT RAISE(ABORT, 'invoice payment does not match operation or reversal'); END;
