-- Full reversal identity cannot be expressed by CHECK, which cannot read another table.
CREATE TRIGGER `invoice_payment_operations_reversal_insert` BEFORE INSERT ON `invoice_payment_operations`
FOR EACH ROW WHEN (NEW.`kind` = 'reversal' AND NOT EXISTS (
  SELECT 1 FROM `invoice_payments` p WHERE p.`id` = NEW.`reversed_payment_id`
    AND p.`household_id` = NEW.`household_id` AND p.`invoice_id` = NEW.`invoice_id`
    AND p.`account_id` = NEW.`account_id` AND p.`amount_cents` = NEW.`amount_cents`
)) OR EXISTS (
  SELECT 1 FROM `invoice_payments` p WHERE p.`operation_id` = NEW.`id`
    AND (NEW.`kind` IS NOT 'payment' OR p.`household_id` IS NOT NEW.`household_id`
      OR p.`invoice_id` IS NOT NEW.`invoice_id` OR p.`account_id` IS NOT NEW.`account_id`
      OR p.`created_by_user_id` IS NOT NEW.`created_by_user_id`
      OR p.`amount_cents` IS NOT NEW.`amount_cents` OR p.`paid_at` IS NOT NEW.`occurred_on`)
) BEGIN SELECT RAISE(ABORT, 'invoice operation does not match original payment or linked payment'); END;
